import { Canvas } from "@react-three/fiber";
import BubbleText from "../ui/BubbleText";
import { Suspense, useEffect, useState } from "react";
import "./Hero.css";

interface HeroProps {
  className: string;
  setIsLoaded: React.Dispatch<React.SetStateAction<boolean>>;
}

function Hero({ className, setIsLoaded }: HeroProps) {
  const [scale, setScale] = useState(window.innerWidth < 768 ? 0.35 : 0.65);

  useEffect(() => {
    const handleResize = () => {
      setScale(window.innerWidth < 768 ? 0.35 : 0.65);
    };
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  return (
    <>
      <section id="hero" className={`section hero ${className}`}>
        <div className="hero-content">
          <h1>GAITANO'S</h1>
          <div className="bubble-container">
            <Canvas>
              <Suspense fallback={null}>
                <ambientLight intensity={0.1} />
                <directionalLight color="red" position={[0, 0, 5]} />
                <BubbleText
                  setIsLoaded={setIsLoaded}
                  rotationX={0}
                  rotationY={0}
                  rotationZ={0}
                  scale={scale}
                />
              </Suspense>
            </Canvas>
          </div>
        </div>
      </section>
    </>
  );
}

export default Hero;

